def update_reservation_passengers(reservation_id: str, passengers: list):
    """
    Update the passenger information (names / dates of birth) of a reservation.

    The NUMBER of passengers cannot change: pass exactly one passenger object per
    existing passenger on the reservation. Each object is
    {"first_name": "Noah", "last_name": "Muller", "dob": "1980-06-12"} where dob is
    'YYYY-MM-DD'. If you leave a passenger's dob out (or send only the changed
    names), the missing dob is filled in from the passenger already on the
    reservation whose name matches, so an unchanged detail never has to be re-typed.

    Args:
        reservation_id: The reservation ID, such as 'ZFA04Y'.
        passengers: A list of passenger objects, each {"first_name": "Noah", "last_name": "Muller", "dob": "1980-06-12"}. Same count as the current reservation.

    Returns:
        The updated reservation.

    Raises:
        ValueError: If the reservation is not found.
        ValueError: If the number of passengers does not match.
    """
    def _as_dict(x):
        if isinstance(x, dict):
            return x
        if hasattr(x, "model_dump"):
            try:
                return x.model_dump()
            except Exception:
                return None
        return None

    # Build name -> dob and a positional list from the existing reservation, so a
    # missing/blank dob can be backfilled without changing any provided value.
    existing = []
    name_dob = {}
    res = _as_dict(env_get_reservation_details(reservation_id=reservation_id))
    if res:
        for p in (res.get("passengers") or []):
            p = _as_dict(p) or (p if isinstance(p, dict) else {})
            existing.append(p)
            if p.get("dob"):
                fn = str(p.get("first_name", "")).strip().lower()
                ln = str(p.get("last_name", "")).strip().lower()
                name_dob[(fn, ln)] = p["dob"]

    npass = []
    for i, p in enumerate(passengers):
        if not isinstance(p, dict):
            npass.append(p)
            continue
        q = dict(p)
        if not q.get("dob"):
            for alt in ("date_of_birth", "dateOfBirth", "birth_date", "birthday"):
                if q.get(alt):
                    q["dob"] = q[alt]
                    break
        fn = str(q.get("first_name", "")).strip().lower()
        ln = str(q.get("last_name", "")).strip().lower()
        if not q.get("dob"):
            cand = name_dob.get((fn, ln)) or name_dob.get((fn, ""))
            if not cand and i < len(existing):
                cand = existing[i].get("dob")
            if cand:
                q["dob"] = cand
        npass.append({
            "first_name": q.get("first_name"),
            "last_name": q.get("last_name"),
            "dob": q.get("dob"),
        })

    return env_update_reservation_passengers(reservation_id=reservation_id, passengers=npass)
